// Die Zeilen aus dem Webhook-Body in einzelne Items zerlegen; der
// Data-Table-Knoten schreibt eine Zeile pro Item. Die Feldnamen der Items
// müssen exakt den Spalten von pw_config entsprechen: der Knoten danach
// mappt per autoMapInputData.
//
// Erwartetes Format (= Inhalt von setup/n8n/config.json):
//   [ { "key": "mail_betrieb", "value": "…", "hint": "…" }, … ]

const body = $('Webhook').first().json.body;
const zeilen = Array.isArray(body) ? body : body?.zeilen;

if (!Array.isArray(zeilen) || zeilen.length === 0) {
  throw new Error('Kein Array im Body. Erwartet wird der Inhalt von setup/n8n/config.json: [{"key":"…","value":"…","hint":"…"}, …]');
}

return zeilen.map((z, i) => {
  const key = String(z.key ?? '').trim();
  if (!key) {
    throw new Error('Eintrag ' + (i + 1) + ' hat kein "key"-Feld.');
  }
  return { json: {
    key,
    // Leere Werte sind erlaubt: die Tabelle darf mit unausgefüllten Zeilen
    // ausgeliefert werden, damit im Browser sichtbar ist, WAS noch fehlt.
    // Gemeckert wird erst beim Lesen, im Konfigurations-Node des Workflows,
    // der den Wert tatsächlich braucht.
    value: String(z.value ?? ''),
    hint: String(z.hint ?? '')
  } };
});

// Kurze Quittung für apply.sh; der Aufrufer soll sehen, dass wirklich
// geschrieben wurde, und nicht nur ein leeres 200 bekommen.
const geschrieben = $('Zeilen aufbereiten').all().map(i => i.json.key);
const leer = $('Zeilen aufbereiten').all()
  .filter(i => i.json.value === '')
  .map(i => i.json.key);

return [{ json: {
  tabelle: 'pw_config',
  geschrieben: geschrieben.length,
  keys: geschrieben,
  noch_leer: leer
} }];
